"use strict";(self.webpackChunk_abdm_docs_site=self.webpackChunk_abdm_docs_site||[]).push([["18883"],{37336(e,t,s){s.r(t),s.d(t,{metadata:()=>n,default:()=>l,frontMatter:()=>c,contentTitle:()=>d,toc:()=>p,assets:()=>h});var n=JSON.parse('{"id":"nhcx/v1/api/other/endpoints/other-v3-api-docs","title":"Get the openAPI 3 document (status service)","description":"Serves the status service\'s OpenAPI 3 document, optionally filtered by a group query parameter; a discovery endpoint, not a protocol API.","source":"@site/docs/nhcx/v1/api/other/endpoints/other-v3-api-docs.mdx","sourceDirName":"nhcx/v1/api/other/endpoints","slug":"/nhcx/v1/api/other/endpoints/other-v3-api-docs","permalink":"/docs/pr-30/docs/nhcx/v1/api/other/endpoints/other-v3-api-docs","draft":false,"unlisted":false,"tags":[],"version":"current","lastUpdatedAt":null,"frontMatter":{"title":"Get the openAPI 3 document (status service)","sidebar_label":"Get the openAPI 3 document (status service)","sidebar_class_name":"api-method api-method--get","description":"Serves the status service\'s OpenAPI 3 document, optionally filtered by a group query parameter; a discovery endpoint, not a protocol API.","hide_table_of_contents":true,"hide_title":true,"wrapperClassName":"api-doc","source":"nhcx-other.yaml","generated":true},"sidebar":"nhcx-v1-api","previous":{"title":"Delete records (troubleshooting)","permalink":"/docs/pr-30/docs/nhcx/v1/api/other/endpoints/other-v1-delete"},"next":{"title":"Get the swagger 2 document (status service)","permalink":"/docs/pr-30/docs/nhcx/v1/api/other/endpoints/other-v2-api-docs"}}'),a=s(62540),r=s(43023),o=s(75064),i=JSON.parse('{"id":"other_v3_api_docs","module":"Other","moduleId":"other","kind":"operation","method":"GET","path":"/v3/api-docs","server":"https://apisbx.abdm.gov.in/hcx","servers":[{"url":"https://apisbx.abdm.gov.in/hcx","description":"Sandbox, NHCX exchange."},{"url":"https://apisprod.nha.gov.in/hcx","description":"Production."}],"summary":"OpenAPI 3 document (status service)","title":"Get the openAPI 3 document (status service)","description":"Serves the status service\'s OpenAPI 3 document, optionally filtered by a group query parameter; a discovery endpoint, not a protocol API.\\n\\n### Business purpose\\n\\nIntegrators need a machine-readable contract for the Status API in order to generate clients, validate their requests and confirm the server prefix. This endpoint serves that contract in OpenAPI 3 form for the status service (statushcxservice, OpenAPI 3.0.1, service version 1.0.0). It carries no claim-settlement data and involves no payer or provider business logic; its value is purely in making the /v1/status operation discoverable and verifiable during integration and troubleshooting.\\n\\n### When to use\\n\\nUse it during integration setup, when generating or refreshing an API client, and when a status call is failing and you want to confirm the exact schema and server prefix the service advertises. The endpoint index lists it as endpoint 19 with an optional group query parameter. It is not part of any transaction workflow and is not referenced by the sandbox exit checklists.\\n\\n### Preconditions\\n\\n- A GET request to the status service host; the OpenAPI documents in this corpus were captured from https://hcxsbx.ABDM.gov.in//api-docs, and the status service declares the server prefix /statushcxservice.\\n- No JWE envelope, no x-hcx-* protocol headers and no correlation ID; the docs do not state that a Bearer token is required for these discovery endpoints.\\n- No request body.\\n\\n### Postconditions\\n\\nThe service returns HTTP 200 with a JSON OpenAPI 3 document describing the status service: its info block, the /statushcxservice server entry and the /v1/status operation with its StatusSuccessResponse responses. Nothing changes on NHCX and no callback follows. The document is a description of the service as deployed and may differ from the handbook\'s gateway-side conventions, which the docs flag as an unresolved conflict.\\n\\n### Common mistakes\\n\\n- Pointing at the gateway base https://apisbx.ABDM.gov.in/pmjay/sbxhcx and expecting the per-service spec host; the docs advise swapping between the two URL shapes when a path 404s.\\n- Treating the served document as the integration contract for gateway traffic; the handbook\'s gateway base and header conventions take precedence where the two disagree.\\n- Sending a POST or a JSON body to a GET discovery endpoint.\\n- Wrapping the call in JWE or adding x-hcx-* headers, which only apply to protocol APIs such as /v1/status.\\n\\n### Best practices\\n\\n- Use these endpoints for exploration and client generation in the sandbox, and cache the document rather than fetching it on every run.\\n- Diff the served document against the corpus (Status service: OpenAPI 3.0.1, version 1.0.0) when behaviour changes unexpectedly.\\n- Never let production traffic depend on the availability of the documentation endpoints.\\n- Keep the /v1/status protocol rules in mind when reading the spec: x-hcx-correlation_ID must carry the original request\'s correlation ID.\\n\\n### Related scenario\\n\\nA hospital\'s integration team is building status polling for stalled preauthorisations. Before wiring /v1/status, an engineer fetches /v3/api-docs from the status service host, confirms the server prefix and the response schema, and generates a typed client. The team then implements the status request with the original correlation ID in x-hcx-correlation_ID, handles the synchronous request.queued and request.dispatched outcomes, and receives the payer\'s answer on the status callback.\\n\\n### Specification\\n\\nChapter [Environments and addresses](/docs/nhcx/v1/reference/environments-and-addresses) of the NHCX integration specification.","security":[{"name":"bearerAuth","type":"http","scheme":"bearer","description":"On every NHCX call, the token goes in a header called `bearer_auth`, with the word `Bearer` and a space in front. The sources are not unanimous: the authentication page and the FAQ both write the example as `Authorization`, and the notification endpoint uses `Authorization`. The safe course, and what the adapter does, is to send both headers with the same value."}],"headers":[{"name":"bearer_auth","required":true,"description":"It is `bearer_auth`, not `Authorization`, on NHCX\'s own endpoints.","example":"Bearer <access token>","type":"string"}],"pathParams":[],"queryParams":[],"body":[],"responses":[{"status":"200","description":"The service returns HTTP 200 with a JSON OpenAPI 3 document describing the status service: its info block, the /statushcxservice server entry and the /v1/status operation with its StatusSuccessResponse responses.","example":{"openapi":"3.0.1","info":{"title":"Status service","version":"1.0.0"},"servers":[{"url":"/statushcxservice"}],"paths":{"/v1/status":{"post":{"operationId":"status","responses":{"202":{"description":"Accepted"}}}}}}}],"tag":"Other operations","curl":"curl --request GET \\\\\\n  --url https://apisbx.abdm.gov.in/hcx/v3/api-docs \\\\\\n  --header \'Authorization: Bearer <ACCESS_TOKEN_FROM_SESSIONS_CALL>\' \\\\\\n  --header \'bearer_auth: Bearer <access token>\'","samples":[{"id":"curl","label":"cURL","language":"bash","code":"curl --request GET \\\\\\n  --url https://apisbx.abdm.gov.in/hcx/v3/api-docs \\\\\\n  --header \'Authorization: Bearer <ACCESS_TOKEN_FROM_SESSIONS_CALL>\' \\\\\\n  --header \'bearer_auth: Bearer <access token>\'"},{"id":"python","label":"Python","language":"python","code":"import requests\\n\\nresponse = requests.get(\\n    \\"https://apisbx.abdm.gov.in/hcx/v3/api-docs\\",\\n    headers={\\n        \\"Authorization\\": \\"Bearer <ACCESS_TOKEN_FROM_SESSIONS_CALL>\\",\\n        \\"bearer_auth\\": \\"Bearer <access token>\\",\\n    },\\n)\\n\\nprint(response.status_code, response.text)"},{"id":"node","label":"Node","language":"javascript","code":"const response = await fetch(\\"https://apisbx.abdm.gov.in/hcx/v3/api-docs\\", {\\n  method: \\"GET\\",\\n  headers: {\\n    \\"Authorization\\": \\"Bearer <ACCESS_TOKEN_FROM_SESSIONS_CALL>\\",\\n    \\"bearer_auth\\": \\"Bearer <access token>\\",\\n  },\\n});\\n\\nconsole.log(response.status, await response.text());"}]}');let c={title:"Get the openAPI 3 document (status service)",sidebar_label:"Get the openAPI 3 document (status service)",sidebar_class_name:"api-method api-method--get",description:"Serves the status service's OpenAPI 3 document, optionally filtered by a group query parameter; a discovery endpoint, not a protocol API.",hide_table_of_contents:!0,hide_title:!0,wrapperClassName:"api-doc",source:"nhcx-other.yaml",generated:!0},d,h={},p=[];function u(e){return(0,a.jsx)(o.A,{operation:i})}function l(e={}){let{wrapper:t}={...(0,r.R)(),...e.components};return t?(0,a.jsx)(t,{...e,children:(0,a.jsx)(u,{...e})}):u(e)}}}]);